def example_request():
    """Human-designed synthetic panel, not an RPI recipe or agent-selected design."""
    specimens = []
    for temperature in (600, 650, 700):
        for repeat in range(3):
            sid = f"screen-{temperature}-{repeat + 1}"
            conditions = {
                "route": "mqu_f_sps",
                "temperature_c": temperature,
                "pressure_mpa": 50.0,
                "heating_rate_c_min": 100.0,
                "hold_time_s": 30.0,
                "mass_g": 15.0,
                "diameter_mm": 20.0,
                "post_treatment": "none",
                "allow_source_transfer": True,
                "field_alignment": "none",
            }
            specimens.append(
                {
                    "specimen_id": sid,
                    "preparation_id": "prep-" + sid,
                    "cycle_id": "cycle-" + sid,
                    "conditions": conditions,
                    "measurements": ["density_g_cm3", "sps_log"]
                    + (["grain_size_nm"] if repeat == 0 else []),
                }
            )
    return {
        "lot_id": "synthetic-melt-spun-lot",
        "origin": "synthetic",
        "specimens": specimens,
        "design_origin": "human_proposed_simulation_panel_not_RPI_approved_recipe",
    }


def initialize_simulation(state, investigator_directory, *, campaign_id, max_specimens=36,
                          microstructure=False, task_context=None):
    """Start a fresh, portable simulation investigation with attributed source prior.

    Does not submit the panel, select a world, execute a batch or run inference.
    Those remain separate explicit actions. No actual RPI inputs are defaulted.
    """
    if microstructure:
        from .models.coverage import coverage_source_packet
        packet = coverage_source_packet()
    else:
        packet = public_source_packet()
    panel = example_request()
    if microstructure:
        for specimen in panel["specimens"]:
            specimen["conditions"].update(process_stage="initial_sps", die_material="graphite",
                measurement_context=packet["scientific_tools"]["measurement_context"])
            if "grain_size_nm" in specimen["measurements"]:
                specimen["measurements"] += ["microstructure", "grain_d90_nm",
                    "coarse_number_fraction", "porosity_area_fraction"]
    packet["task"] = {
        "material_question": "Investigate the density/microstructure tradeoff under lower-temperature SPS and select worthwhile follow-up evidence.",
        "starting_panel": panel,
        "starting_panel_origin": "human proposal; you may evaluate whether it is worthwhile",
        "initial_model_origin": "owner-supplied source-only prior, not agent discovery",
        "supported_simulation": {
            "route": "mqu_f_sps",
            "temperature_c": [550, 800],
            "pressure_mpa": [50, 50],
            "hold_time_s": [30, 30],
            "heating_rate_c_min": [100, 100],
            "mass_g": [15, 15],
            "diameter_mm": [20, 20],
            "post_treatment": ["none"],
            "measurements": ["density_g_cm3", "grain_size_nm", "sps_log"],
            "boundary": "Conditional computational envelope, not laboratory operating approval",
        },
        "available_resources": {
            "max_requested_specimens": max_specimens,
            "meaning": "Declared synthetic inventory; no physical powder purchased",
        },
        "scientific_freedom": "Choose models, counterfactual calculations, supported experiments, repeats, diagnostic measurements, revisions or retention, and stopping. Unsupported interventions need new capability evidence, not invented outcomes.",
        "material_claim_limits": [
            "RPI powder lot, reference recipe and meaningful density margin remain pending",
            "No confirmed magnet grade, magnetic measurements, economic benefit or customer order",
            "No initial grain state measured; post-process grain differences are not proven grain growth",
        ],
        "comparison_advice": "Use actual delivered histories. Small nuisance deviations require explicit applicability assumptions; literal equality to requested settings is not generally justified.",
    }
    if microstructure:
        packet["task"]["supported_simulation"]["measurements"] += ["microstructure",
            "grain_d90_nm", "coarse_number_fraction", "porosity_area_fraction"]
        packet["task"]["supported_simulation"]["process_stage"] = ["initial_sps"]
        packet["task"]["supported_simulation"]["die_material"] = ["graphite"]
        packet["task"]["material_question"] += " Avoid declaring microstructure success from mean grains alone."
    if task_context is not None:
        if not isinstance(task_context, dict):
            raise ValueError("task_context must be a public JSON object")
        # Prospective, explicitly attributed context; never a private world or
        # a post-outcome source edit. The investigator freezes it on creation.
        packet["task"]["additional_public_context"] = json.loads(
            json.dumps(task_context, allow_nan=False)
        )
    with Campaign.open(
        state,
        {"campaign_id": campaign_id, "execution_mode": "synthetic", "max_specimens": max_specimens},
    ) as campaign:
        if campaign.models() or campaign.state()["requests"]:
            raise ValueError(
                "initialization requires a fresh campaign; resume existing state instead"
            )
        investigator = Investigator(campaign, investigator_directory, sources=packet)
        try:
            staged = investigator.call(
                "owner-source-prior-stage", "stage_model", {"source": bootstrap_model_source()}
            )
            adopted = investigator.call(
                "owner-source-prior-adopt",
                "adopt_model",
                {
                    "source_sha256": staged["source_sha256"],
                    "test_request": panel,
                    "rationale": "Owner-supplied frozen literature prior. Not an agent learning response or RPI calibration.",
                },
            )
            return {
                "campaign_id": campaign_id,
                "status": "initialized_no_experiment_executed",
                "model_id": adopted["model_id"],
                "source_packet_sha256": investigator.state()["source_packet_sha256"],
                "execution_mode": "synthetic",
                "physical_execution": "HOLD",
            }
        finally:
            investigator.close()


def _immutable_write(path, data):
    """Fsync then atomically publish without replacing any existing artifact."""
    if path.is_symlink():
        raise ValueError("immutable artifacts cannot be symlinks")
    if path.exists():
        if path.read_bytes() != data:
            raise ValueError(f"immutable generated artifact conflict: {path.name}")
        return
    descriptor, name = tempfile.mkstemp(prefix=".pending-", dir=path.parent)
    temporary = Path(name)
    try:
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            os.link(temporary, path)
        except FileExistsError:
            if path.is_symlink() or path.read_bytes() != data:
                raise ValueError(f"immutable generated artifact conflict: {path.name}") from None
        directory_fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        temporary.unlink(missing_ok=True)


def _external_directory(path):
    proposed = Path(path).expanduser()
    if proposed.is_symlink():
        raise ValueError("owner artifact directory cannot be a symlink")
    path = proposed.resolve()
    validate_private_path(path)
    path.mkdir(parents=True, exist_ok=True, mode=0o700)
    return path


def materialize_synthetic_delivery(delivery, directory):
    """Export simulation-native records as labeled raw fixtures; never create SEM images.

    The complete private response remains in native owner artifacts. This public
    measurement export excludes private scenario fingerprints. Normalized CSVs
    are derivations, not claimed vendor instrument exports.
    """
    directory = _external_directory(directory)
    public = json.loads(json.dumps(delivery, allow_nan=False))
    public["provenance"] = {
        k: delivery["provenance"][k]
        for k in ("evidence_class", "model_version", "physical_execution")
    }
    public["provenance"]["export_status"] = "measurement_export_private_execution_context_excluded"
    original = json.dumps(public, sort_keys=True, indent=2, allow_nan=False).encode()
    original_name = "synthetic-response.json"
    _immutable_write(directory / original_name, original)
    augmented = json.loads(original)
    files = {original_name: directory / original_name}
    for observation in augmented["observations"]:
        observation["source_file"] = original_name
        if observation["quantity"] != "sps_log":
            continue
        sid = observation["specimen_id"]
        safe_id = hashlib.sha256(sid.encode()).hexdigest()[:16]
        name = f"synthetic-sps-{safe_id}.csv"
        log = observation["value"]
        if "method" not in observation:
            method = log.get("method")
            if not isinstance(method, str) or not method.strip():
                raise ValueError("SPS log export requires an attributed method in the observation or raw log")
            # Preserve the method already recorded in the bound original. This
            # attributes the CSV derivation without inventing an instrument or
            # changing any simulated reading.
            observation["method"] = method
        buffer = io.StringIO(newline="")
        writer = csv.writer(buffer)
        writer.writerow(["time_s", "temperature_C", "pressure_MPa", "displacement_mm"])
        writer.writerows(
            zip(
                log["time_s"],
                log["temperature_c"],
                log["pressure_mpa"],
                log["displacement_mm"],
                strict=True,
            )
        )
        _immutable_write(directory / name, buffer.getvalue().encode())
        files[name] = directory / name
        observation["source_file"] = name
        observation["derived_from"] = [original_name]
        observation["export_status"] = "normalized_simulator_export_not_vendor_data"
    return augmented, files


def fulfill_simulation(state, request_id, *, runtime, artifact_directory, world_config, seed):
    """Execute one requested synthetic batch natively, import, but do NOT release it.

    Automatic review is simulation-only. Physical requests cannot enter this path.
    Native preflight/admission/validation must succeed before measurement import.
    """
    directory = _external_directory(artifact_directory)
    with Campaign.open(state) as campaign:
        request = campaign.request(request_id)["request"]
        if request["origin"] != "synthetic":
            raise ValueError("physical requests cannot use automatic simulation fulfillment")
        # Owner-private and immutable across the investigation, including restarts.
        # Do not publish this context or its fingerprint to the investigator.
        _immutable_write(
            Path(state) / "owner_simulation_context.json",
            json.dumps(
                {"world_config": world_config, "seed": seed},
                sort_keys=True,
                indent=2,
                allow_nan=False,
            ).encode(),
        )
        prior = [d for d in campaign.store.all("delivery") if d["request_id"] == request_id]
        if prior:
            return {
                "status": "already_received",
                "delivery_id": prior[-1]["delivery_id"],
                "request_id": request_id,
                "evidence_released": campaign.store.has("release", prior[-1]["delivery_id"]),
            }
        campaign.accept(request_id, "synthetic-operator", "Conditional simulator execution only")
        try:
            executor = NativeSPSExecutor(runtime, directory / "native")
            delivery = executor(request, world_config=world_config, seed=seed, replay=True)
        except (NativeExecutionError, OSError, subprocess.TimeoutExpired) as exc:
            attempt = uuid.uuid4().hex
            _immutable_write(
                directory / f"owner-failure-{attempt}.json",
                json.dumps({"error": str(exc)}, indent=2).encode(),
            )
            failure = campaign.record_execution_failure(
                request_id,
                "synthetic-operator",
                "NATIVE_EXECUTION_UNAVAILABLE",
                "Native simulation admission, execution or validation failed. Owner must inspect private execution receipts; no material result was returned.",
                call_id="native-attempt-" + attempt,
            )
            return {**failure, "evidence_released": False, "physical_execution": False}
        augmented, files = materialize_synthetic_delivery(
            delivery, directory / delivery["delivery_id"]
        )
        pending = next(r for r in campaign.state()["requests"] if r["request_id"] == request_id)
        if pending["active_execution_failure"]:
            augmented["recovers_failure_id"] = pending["active_execution_failure"]["failure_id"]
        received = campaign.receive(request_id, augmented, files)
        return {
            **received,
            "native_receipt": executor.last_receipt,
            "evidence_released": False,
            "physical_execution": False,
        }
